const require_is = require("../utils/is.js");
const require_index = require("../useIsomorphicLayoutEffect/index.js");
let react = require("react");
//#region src/useEvent/index.ts
/**
* keep function reference immutable
*/
const useEvent = (fn) => {
	if (require_is.isDev) {
		if (!require_is.isFunction(fn)) console.error(`useEvent expected parameter is a function, got ${typeof fn}`);
	}
	const handlerRef = (0, react.useRef)(fn);
	require_index.useIsomorphicLayoutEffect(() => {
		handlerRef.current = fn;
	}, [fn]);
	return (0, react.useCallback)((...args) => {
		const fn = handlerRef.current;
		return fn(...args);
	}, []);
};
//#endregion
exports.useEvent = useEvent;
